1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.NivelClube;
4	import com.loja.checkout.domain.Regiao;
5	import com.loja.checkout.domain.cupom.*;
6	import com.loja.checkout.domain.modalidade.*;
7	import com.loja.checkout.domain.pagamento.*;
8	import com.loja.checkout.dto.*;
9	import com.loja.checkout.exception.CheckoutException;
10	import com.loja.checkout.exception.CodigoErro;
11	import org.springframework.stereotype.Service;
12	
13	import java.math.BigDecimal;
14	import java.util.List;
15	import java.util.Map;
16	
17	import static com.loja.checkout.service.ArredondamentoUtil.arredondar;
18	
19	@Service
20	public class CalculadoraResumo {
21	
22	    private final Map<String, ModalidadeEntrega> modalidades = Map.of(
23	        "ECONOMICA", new Economica(),
24	        "EXPRESSA", new Expressa(),
25	        "RETIRADA_LOJA", new RetiradaLoja(),
26	        "MOTOBOY", new Motoboy()
27	    );
28	
29	    private final Map<String, Cupom> cupons = Map.of(
30	        "BEMVINDO10", new BemVindo10(),
31	        "MENOS50", new Menos50(),
32	        "FRETEGRATIS", new FreteGratis(),
33	        "LEVE3PAGUE2", new Leve3Pague2()
34	    );
35	
36	    private final Map<String, FormaPagamento> formasPagamento = Map.of(
37	        "PIX", new Pix(),
38	        "CARTAO", new Cartao(),
39	        "BOLETO", new Boleto()
40	    );
41	
42	    public ResumoResponse calcular(PedidoRequest request) {
43	        validarPedido(request);
44	
45	        NivelClube nivelClube = parseNivelClube(request.nivelClube());
46	        Regiao regiao = parseRegiao(request.regiao());
47	
48	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(request.itens());
49	        BigDecimal pesoTotal = calcularPesoTotal(request.itens());
50	
51	        ModalidadeEntrega modalidade = obterModalidade(request.modalidadeEntrega());
52	        validarModalidade(modalidade, pesoTotal);
53	
54	        BigDecimal frete = nivelClube.isFreteGratis()
55	            ? BigDecimal.ZERO.setScale(2)
56	            : modalidade.calcularFrete(pesoTotal);
57	
58	        BigDecimal descontoCupom = calcularDescontoCupom(
59	            request.cupom(),
60	            subtotalProdutos,
61	            frete,
62	            request.itens()
63	        );
64	
65	        BigDecimal seguro = arredondar(subtotalProdutos.multiply(regiao.getPercentualSeguro()));
66	
67	        BigDecimal totalPedido = subtotalProdutos
68	            .subtract(descontoCupom)
69	            .add(frete)
70	            .add(seguro);
71	
72	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
73	        FormaPagamento formaPagamento = obterFormaPagamento(request.formaPagamento());
74	
75	        validarParcelamento(formaPagamento, parcelas);
76	        validarFormaPagamento(formaPagamento, totalPedido);
77	
78	        BigDecimal ajustePagamento = formaPagamento.calcularAjuste(totalPedido, parcelas);
79	        BigDecimal totalFinal = arredondar(totalPedido.add(ajustePagamento));
80	        BigDecimal valorParcela = formaPagamento.calcularValorParcela(totalPedido, ajustePagamento, parcelas);
81	
82	        BigDecimal credito = arredondar(subtotalProdutos.multiply(nivelClube.getPercentualCredito()));
83	        boolean brinde = nivelClube.isElegiveParaBrinde()
84	            && subtotalProdutos.compareTo(new BigDecimal("500.00")) > 0;
85	
86	        return new ResumoResponse(
87	            subtotalProdutos,
88	            descontoCupom,
89	            frete,
90	            modalidade.getPrazoEntregaDias(),
91	            seguro,
92	            ajustePagamento,
93	            totalFinal,
94	            parcelas,
95	            valorParcela,
96	            credito,
97	            brinde
98	        );
99	    }
100	
101	    private void validarPedido(PedidoRequest request) {
102	        if (request.itens() == null || request.itens().isEmpty()) {
103	            throw new CheckoutException(CodigoErro.PEDIDO_INVALIDO);
104	        }
105	
106	        for (ItemRequest item : request.itens()) {
107	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0 ||
108	                item.quantidade() == null || item.quantidade() <= 0 ||
109	                item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
110	                throw new CheckoutException(CodigoErro.PEDIDO_INVALIDO);
111	            }
112	        }
113	    }
114	
115	    private NivelClube parseNivelClube(String nivel) {
116	        if (nivel == null) {
117	            throw new CheckoutException(CodigoErro.NIVEL_CLUBE_INVALIDO);
118	        }
119	        try {
120	            return NivelClube.valueOf(nivel);
121	        } catch (IllegalArgumentException e) {
122	            throw new CheckoutException(CodigoErro.NIVEL_CLUBE_INVALIDO);
123	        }
124	    }
125	
126	    private Regiao parseRegiao(String regiao) {
127	        if (regiao == null) {
128	            throw new CheckoutException(CodigoErro.REGIAO_INVALIDA);
129	        }
130	        try {
131	            return Regiao.valueOf(regiao);
132	        } catch (IllegalArgumentException e) {
133	            throw new CheckoutException(CodigoErro.REGIAO_INVALIDA);
134	        }
135	    }
136	
137	    private BigDecimal calcularSubtotalProdutos(List<ItemRequest> itens) {
138	        BigDecimal subtotal = BigDecimal.ZERO;
139	        for (ItemRequest item : itens) {
140	            BigDecimal totalItem = item.precoUnitario().multiply(new BigDecimal(item.quantidade()));
141	            subtotal = subtotal.add(totalItem);
142	        }
143	        return arredondar(subtotal);
144	    }
145	
146	    private BigDecimal calcularPesoTotal(List<ItemRequest> itens) {
147	        BigDecimal peso = BigDecimal.ZERO;
148	        for (ItemRequest item : itens) {
149	            peso = peso.add(item.pesoKg().multiply(new BigDecimal(item.quantidade())));
150	        }
151	        return peso;
152	    }
153	
154	    private ModalidadeEntrega obterModalidade(String codigo) {
155	        if (codigo == null || !modalidades.containsKey(codigo)) {
156	            throw new CheckoutException(CodigoErro.MODALIDADE_INVALIDA);
157	        }
158	        return modalidades.get(codigo);
159	    }
160	
161	    private void validarModalidade(ModalidadeEntrega modalidade, BigDecimal pesoTotal) {
162	        if (!modalidade.aceitaPedido(pesoTotal)) {
163	            throw new CheckoutException(CodigoErro.MODALIDADE_INDISPONIVEL);
164	        }
165	    }
166	
167	    private BigDecimal calcularDescontoCupom(String codigo, BigDecimal subtotal, BigDecimal frete, List<ItemRequest> itens) {
168	        if (codigo == null || codigo.isEmpty()) {
169	            return BigDecimal.ZERO.setScale(2);
170	        }
171	
172	        if (!cupons.containsKey(codigo)) {
173	            throw new CheckoutException(CodigoErro.CUPOM_INVALIDO);
174	        }
175	
176	        Cupom cupom = cupons.get(codigo);
177	
178	        if (!cupom.aplicavel(subtotal)) {
179	            throw new CheckoutException(CodigoErro.CUPOM_NAO_APLICAVEL);
180	        }
181	
182	        List<Cupom.ItemCupom> itensCupom = itens.stream()
183	            .map(i -> new Cupom.ItemCupom(i.nome(), i.precoUnitario(), i.quantidade()))
184	            .toList();
185	
186	        return cupom.calcularDesconto(subtotal, frete, itensCupom);
187	    }
188	
189	    private FormaPagamento obterFormaPagamento(String codigo) {
190	        if (codigo == null || !formasPagamento.containsKey(codigo)) {
191	            throw new CheckoutException(CodigoErro.FORMA_PAGAMENTO_INVALIDA);
192	        }
193	        return formasPagamento.get(codigo);
194	    }
195	
196	    private void validarParcelamento(FormaPagamento forma, int parcelas) {
197	        if (!forma.aceitaParcelamento(parcelas)) {
198	            throw new CheckoutException(CodigoErro.PARCELAMENTO_INVALIDO);
199	        }
200	    }
201	
202	    private void validarFormaPagamento(FormaPagamento forma, BigDecimal total) {
203	        if (!forma.aceitaPedido(total)) {
204	            throw new CheckoutException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
205	        }
206	    }
207	}
