3	import com.loja.checkout.service.ArredondamentoUtil;
4	import java.math.BigDecimal;
5	import java.math.RoundingMode;
6	
7	public class Cartao implements FormaPagamento {
8	
9	    private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
10	
11	    @Override
12	    public BigDecimal calcularAjuste(BigDecimal totalPedido, int parcelas) {
13	        if (parcelas <= 3) {
14	            return BigDecimal.ZERO.setScale(2);
15	        }
16	
17	        BigDecimal valorParcela = calcularParcelaComJuros(totalPedido, parcelas);
18	        BigDecimal totalFinal = valorParcela.multiply(new BigDecimal(parcelas));
19	        return ArredondamentoUtil.arredondar(totalFinal.subtract(totalPedido));
20	    }
21	
22	    @Override
23	    public BigDecimal calcularValorParcela(BigDecimal totalPedido, BigDecimal ajuste, int parcelas) {
24	        if (parcelas <= 3) {
25	            return ArredondamentoUtil.arredondar(totalPedido.divide(new BigDecimal(parcelas), 10, RoundingMode.HALF_EVEN));
26	        }
27	
28	        return calcularParcelaComJuros(totalPedido, parcelas);
29	    }
30	
31	    @Override
32	    public boolean aceitaParcelamento(int parcelas) {
33	        return parcelas >= 1 && parcelas <= 12;
34	    }
35	
36	    @Override
37	    public boolean aceitaPedido(BigDecimal totalPedido) {
38	        return true;
39	    }
40	
41	    private BigDecimal calcularParcelaComJuros(BigDecimal total, int parcelas) {
42	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_JUROS);
43	        BigDecimal potencia = umMaisTaxa.pow(parcelas);
44	        BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(potencia, 10, RoundingMode.HALF_EVEN));
45	        BigDecimal parcela = total.multiply(TAXA_JUROS).divide(denominador, 10, RoundingMode.HALF_EVEN);
46	        return ArredondamentoUtil.arredondar(parcela);
47	    }
48	}
